class Solution { private void add(PriorityQueue<Integer> heap,int value,int k){if(value<=0||k==0)return;heap.offer(value);if(heap.size()>k)heap.poll();}public int maxStarSum(int[] vals,int[][] edges,int k){PriorityQueue<Integer>[] heaps=new PriorityQueue[vals.length];for(int i=0;i<vals.length;i++)heaps[i]=new PriorityQueue<>();for(int[] edge:edges){add(heaps[edge[0]],vals[edge[1]],k);add(heaps[edge[1]],vals[edge[0]],k);}int answer=Integer.MIN_VALUE;for(int node=0;node<vals.length;node++){int sum=vals[node];for(int value:heaps[node])sum+=value;answer=Math.max(answer,sum);}return answer;} }
